#pragma once
#include <QJsonDocument>
#include <QJsonObject>
namespace {
void drawingSegmentSpacingTests(){
 DrawingEditorModel model;model.snapshot.version={QUuid::createUuid(),{}};model.snapshot.bodies={source(makeBox(Frame3(),10,6,4),1)};model.choices={{1,"Blocco"}};DrawingSheet s;s.drawing.model=model.snapshot.version;DrawingSheetEditor e(s,model);e.resize(1450,900);e.show();QApplication::processEvents();DrawingView v;v.kind=DrawingViewKind::ProjectedEdges;v.scale=3;ok(e.insertView(v,{v.id,"Vista",{75,120},{1}}));e.fitSheet();QApplication::processEvents();
 mode(e,-1);click(e,paper({5,0}));move(e,{90,145});require(items(e,"dimensionPreview")==1,"clic al centro del segmento prepara la misura dell’intero segmento");click(e,{90,145});auto d=last(e);near(e.dimensionResult(d.id).value,10,"segmento intero quotato con un clic e posizionamento");require(d.references.size()==2&&d.references[0].role!=DrawingPointRole::Midpoint&&d.references[1].role!=DrawingPointRole::Midpoint&&d.references[0].curve.edgeName==d.references[1].curve.edgeName,"entrambi gli estremi appartengono al segmento selezionato");ok(e.undo());
 auto style=e.sheet().style;style.extensionGap=1.5;style.dimensionOffset=12;const auto curve=e.curves(v.id)[0].curve.get();ok(e.setDrawingStyle(style));require(e.curves(v.id)[0].curve.get()==curve,"distanze grafiche non ricalcolano il modello");
 mode(e,-1);click(e,paper({5,0}));move(e,{90,125});QPointF previewCenter;for(auto *i:e.canvas()->scene()->items())if(i->data(0).toString()=="dimensionPreview")previewCenter=i->sceneBoundingRect().center();require(previewCenter.y()>=132-.4,"anteprima rispetta distanza minima sul foglio");click(e,{90,125});d=last(e);near(e.dimensionResult(d.id).value,10,"distanza grafica non cambia la misura");QPointF center;for(auto *i:e.canvas()->scene()->items())if(i->data(0).toString()=="dimension"&&i->data(3).toUuid()==d.id){center=i->sceneBoundingRect().center();require(i->rotation()==0,"valore sempre orizzontale");}near(center.y(),previewCenter.y(),"anteprima e posizione finale coincidono",.4);
 bool gap=false;for(auto *i:e.canvas()->scene()->items())if(auto *line=qgraphicsitem_cast<QGraphicsLineItem *>(i)){const auto a=line->line().p1(),b=line->line().p2();if(std::abs(a.x()-75)<1e-7&&std::abs(a.y()-121.5)<.4&&b.y()>131)gap=true;}require(gap,"linea di riferimento staccata dal pezzo di 1,5 mm");
 const auto saved=encoded(e);require(QJsonDocument::fromJson(saved).object()["schema"].toInt()==9,"schema9 per entrambe le distanze");DrawingSheet restored;ok(decodeDrawingSheet(saved,restored));near(restored.style.extensionGap,1.5,"distacco persistente");near(restored.style.dimensionOffset,12,"offset persistente");
 for(int version=1;version<9;++version){auto json=QJsonDocument::fromJson(saved).object();json["schema"]=version;require(!decodeDrawingSheet(QJsonDocument(json).toJson(),restored).isEmpty()&&restored.style.dimensionOffset==12,"downgrade spacing rifiutato atomicamente");}
 auto invalid=QJsonDocument::fromJson(saved).object();auto spacing=invalid["dimensionSpacing"].toObject();spacing["extensionGap"]=-1;invalid["dimensionSpacing"]=spacing;require(!decodeDrawingSheet(QJsonDocument(invalid).toJson(),restored).isEmpty(),"distacco negativo rifiutato");
 const auto output=qEnvironmentVariable("FORGECAD_DIMENSION_SPACING_OUTPUT");if(!output.isEmpty()){QDir().mkpath(output);DrawingPdfReport report;ok(e.exportPdf(output+"/quote.pdf",report));require(e.grab().save(output+"/quote.png"),"QA quote e distanze");}
 ok(e.moveDimension(d.id,{90,121}));require(e.sheet().dimensions.back().position==QPointF(90,121),"testo ancora spostabile liberamente dopo inserimento");ok(e.undo());require(encoded(e)==saved,"Undo spostamento conserva distanze");ok(e.undo());ok(e.undo());require(e.sheet().style.dimensionOffset==0&&e.sheet().drawing.dimensions.empty(),"Undo separati di quota e opzioni");
 std::cout<<"PASS segmento prioritario, Ctrl punto medio, distacco/offset in mm foglio, preview/finale, schema9 e Undo\n";
}
}
